corporate_design.toad_component_blueprint:
canvas {
  size: 920px 560px;
  fill: #FFFFFF;
  font-family: "Helvetica, sans-serif";
}

>red = #DC2626;

rect #transitCard {
  at: center of canvas;
  size: 840px 460px;
  fill: #F9FAFB;
  stroke: >red;
  stroke-width: 2px;
  radius: 6px;
}

text #metroHeader {
  at: top left of #transitCard offset 36px 36px;
  content: "TRANSVIA METROPOL-NETZ // FAHRGAST-INFO";
  font-size: 14px;
  font-weight: 800;
  color: >red;
}

text #metroTitle {
  at: below #metroHeader offset 14px;
  content: "Linie U1: Hauptbahnhof ➔ Flughafen im 3-Min-Takt";
  font-size: 28px;
  font-weight: 800;
  color: #111827;
}
